double result = 0.0;
double a = this->m_a;
double b = this->m_b;
double fa = m_f->eval(a);
double fb = m_f->eval(b);
double c = (a + b) / 2.0;
double fc = m_f->eval(c);
double T1 = (b - a) * (fa + fb) / 2.0;
double T2 = (b - a) / 4.0 * (fa + 2.0 * fc + fb);

result = T2;
double error = std::abs(T2 - T1) / 3.0;

while (error > precision) {
    double d = (a + c) / 2.0;
    double e = (c + b) / 2.0;
    double fd = m_f->eval(d);
    double fe = m_f->eval(e);

    double T1_left = (c - a) * (fa + fd) / 2.0;
    double T2_left = (c - a) / 4.0 * (fa + 2.0 * fd + fc);
    double T1_right = (b - c) * (fc + fe) / 2.0;
    double T2_right = (b - c) / 4.0 * (fc + 2.0 * fe + fb);

    result = T2_left + T2_right;
    error = std::abs(T2_left + T2_right - T1_left - T1_right) / 3.0;

    a = a;
    b = b;
    fa = fa;
    fb = fb;
    c = d;
    fc = fd;
    T1 = T1_left;
    T2 = T2_left;
    d = e;
    fd = fe;
}

return result * m_sign;

